WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM sessions), sessions_sessions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT id, device, browser, country, new_group_flag FROM sessions_sessions ORDER BY new_group_flag DESC NULLS LAST;
